<?php
namespace App\Livewire\LMS\Lessons\Teacher;
use App\Livewire\LMS\Lessons\Concerns\ManagesLessons; use App\Models\{Lesson,Topic}; use Illuminate\Database\Eloquent\Builder; use Livewire\Attributes\Layout;
#[Layout('layouts.lms')] class Index extends ManagesLessons { public function mount():void{$this->authorize('viewAny',Lesson::class);abort_unless(auth()->user()->hasRole('teacher')&&auth()->user()->teacher,403);} protected function topics():Builder{return Topic::with(['classSubject.schoolClass','classSubject.subject','classSubject.teacher'])->whereHas('classSubject',fn(Builder $query)=>$query->where('teacher_id',auth()->user()->teacher->id))->whereHas('classSubject.schoolClass.academicYear',fn(Builder $query)=>$query->where('school_id',$this->schoolId()))->orderBy('sequence');} protected function teacherIdFor(array $data,Topic $topic):int{abort_unless($topic->classSubject->teacher_id===auth()->user()->teacher->id,403);return auth()->user()->teacher->id;} protected function componentView():string{return 'livewire.lms.lessons.teacher.index';} }
